            diag: [{ p: '아이스크림 냉장고에 넣까요', note: 'Consonant stem: 넣 + 을까요.' }, { p: '아이스크림 냉장고에서 넣을까요', note: 'Putting it INTO the fridge: 냉장고에.' }],
