MM.mnemo[4] = {"cards":[{"id":"ko-k3-0088","w":"팔다","cs":"prodat, prodávat","en":"to sell","p":"v","o":"k","ex":"팔까요?","exc":"Máme to prodat? / Prodáme to? (-ㄹ까요 → návrh / otázka na názor)","m":"Nepravidelné sloveso končící na ㄹ – před koncovkami začínajícími na ㄴ, ㅂ, ㅅ tato koncová souhláska ㄹ mizí (např. 팝니다, 파세요). Opakem je 사다 (koupit).","tv":["팔아요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0089","w":"시작하다","cs":"začít, začínat","en":"to start","p":"v","o":"m","ex":"시작할까요?","exc":"Začneme? / Máme začít? (-ㄹ까요 → návrh / otázka na názor)","m":"始 začátek + 作 dělat, tvořit (+ 하다) = začít něco dělat. Podstatné jméno 시작 znamená ‚začátek‘; přímým opakem je 끝나다 nebo 끝내다 (skončit / dokončit).","r":["si-始","jak-作"],"tv":["시작해요"]},{"id":"ko-k3-0090","w":"달리다","cs":"běžet, utíkat","en":"to run","p":"v","o":"k","ex":"달릴까요?","exc":"Poběžíme? / Dáme si běh? (-ㄹ까요 → návrh)","m":"Běh jako sport i jízda vozidla (차가 달리다 = auto jede). Pozor: stejně znějící 달리다 znamená i „viset, záviset“ (~에 달려 있다).","tv":["달려요"]},{"id":"ko-k3-0091","w":"놀다","cs":"hrát si; bavit se, trávit volný čas","en":"to play, to hang out","p":"v","o":"k","ex":"놀까요?","exc":"Půjdeme se pobavit? / Zahrajeme si? (-ㄹ까요 → návrh / otázka na názor)","m":"U dětí znamená ‚hrát si‘, u dospělých spíš ‚jít se pobavit, vyrazit ven s přáteli nebo se jen tak poflakovat‘. Stejně jako u slovesa 팔다 odpadá před ㄴ, ㅂ, ㅅ koncové ㄹ (놉니다, 노세요).","tv":["놀아요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0092","w":"살다","cs":"žít; bydlet","en":"to live","p":"v","o":"k","ex":"살까요?","exc":"Máme tam bydlet? / Budeme tam žít? (-ㄹ까요 → návrh / otázka na názor)","m":"Znamená jak ‚žít‘ (být naživu), tak ‚bydlet na nějakém místě‘ (서울에 살아요 = bydlím v Soulu). I tady mizí koncové ㄹ před ㄴ, ㅂ, ㅅ (삽니다, 사세요).","tv":["살아요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0095","w":"놓다","cs":"položit, dát (někam)","en":"to put, to place","p":"v","o":"k","ex":"책을 어디에 놓을까요?","exc":"Kam mám položit tu knihu? (을 → 4. pád; 에 → kam; -을까요 → otázka na názor)","m":"Položit věc na vodorovnou plochu (třeba na stůl nebo na zem); v mluvené řeči se často používá i sloveso 두다. Při výslovnosti před samohláskou ㅎ zaniká: 놓을까요 [노을까요].","tv":["놓아요"]},{"id":"ko-k3-0096","w":"만들다","cs":"vyrobit, udělat, připravit (jídlo)","en":"to make","p":"v","o":"k","ex":"만들까요?","exc":"Máme to udělat? / Vyrobíme to? (-ㄹ까요 → návrh / otázka na názor)","m":"Označuje ruční výrobu, tvoření nebo vaření konkrétního jídla (김밥을 만들다 = připravit kimbap), na rozdíl od obecného 하다. Koncové ㄹ mizí před ㄴ, ㅂ, ㅅ (만듭니다, 만드세요).","tv":["만들어요"],"irr":"ㄹ (odpadá)"},{"id":"ko-k3-0097","w":"앉다","cs":"sednout si, sedět","en":"to sit","p":"v","o":"k","ex":"여기 앉으세요.","exc":"Posaďte se tady, prosím. (-으세요 → zdvořilá výzva)","m":"Vyslovuje se [안따], ale před samohláskou se ozvou obě souhlásky: 앉으세요 [안즈세요]. Opakem je 일어나다 (vstát) nebo 서다 (stát).","tv":["앉아요"]},{"id":"ko-k3-0098","w":"전화하다","cs":"zavolat, telefonovat","en":"to call, to make a phone call","p":"v","o":"m","ex":"언제 다시 전화할까요?","exc":"Kdy mám zavolat znovu? (-ㄹ까요 → otázka na názor)","m":"電 elektřina + 話 řeč, hovor (+ 하다) = mluvit po elektrickém vedení, tedy zavolat. Kořen 電 znáš i ze slova 전기 (elektřina); komu voláš, vyjadřuje částice 에 nebo 한테.","r":["jeon-電","hwa-話"],"tv":["전화해요"]},{"id":"ko-k3-0099","w":"찍다","cs":"vyfotit, pořídit (fotku, video); namočit; otisknout","en":"to take (a picture)","p":"v","o":"k","ex":"여기에서 사진 찍을까요?","exc":"Vyfotíme se tady? / Uděláme tady fotku? (에서 → kde; -을까요 → návrh)","m":"Základní sloveso ve spojení 사진을 찍다 (vyfotit fotku) nebo 영상을 찍다 (natočit video). Původně znamená ‚vtisknout, píchnout nebo namočit‘ (např. namočit jídlo do omáčky).","tv":["찍어요"]},{"id":"ko-k3-0101","w":"비","cs":"déšť","en":"rain","p":"n","o":"k","ex":"내일 비가 올까요?","exc":"Bude zítra pršet? (가 → 1. pád; -ㄹ까요 → domněnka)","m":"‚Prší‘ se korejsky řekne doslova ‚přichází déšť‘ (비가 오다), případně ‚padá déšť‘ (비가 내리다). Srovnej se sinokorejským kořenem 雨 (우), který je třeba ve slově 우산 (deštník)."},{"id":"ko-k3-0106","w":"주스","cs":"džus, ovocná šťáva","en":"juice","p":"n","o":"e","ex":"우유 마실까요? 주스 마실까요?","exc":"Dáme si mléko, nebo džus? (-ㄹ까요 → návrh)","m":"Výpůjčka z anglického ‚juice‘. Druh ovoce se dává přímo před slovo bez částice, například 오렌지 주스 (pomerančový džus) nebo 사과 주스 (jablečný džus)."},{"id":"ko-k3-0108","w":"이따가","cs":"později (dnes), za chvíli","en":"later (today)","p":"o","o":"k","ex":"지금 바빠요? 이따가 올까요?","exc":"Máš teď napilno? Mám přijít později? (-ㄹ까요 → otázka na názor)","m":"Používá se jen pro budoucnost v rámci dnešního dne (za chvíli, později odpoledne). Pokud jde o vzdálenější budoucnost (za pár dní či let), používá se 나중에; v mluvené řeči se často zkracuje na 이따."},{"id":"ko-k3-0110","w":"산","cs":"hora, kopec","en":"mountain","p":"n","o":"s","ex":"산에 갈까요?","exc":"Vyrazíme na hory? / Půjdeme na horu? (에 → kam; -ㄹ까요 → návrh)","m":"山 hora = hora nebo kopec. Stejný kořen 山 najdeš i ve slovech 등산 (horská turistika) nebo 화산 (sopka).","r":["san-山"]},{"id":"ko-k3-0111","w":"사진","cs":"fotografie, fotka","en":"photo, picture","p":"n","o":"s","ex":"여기에서 사진 찍을까요?","exc":"Vyfotíme se tady? / Uděláme tady fotku? (에서 → kde; -을까요 → návrh)","m":"寫 zobrazit, zachytit + 眞 pravý, skutečný = věrné zachycení skutečnosti, tedy fotografie. Časté spojení: 사진을 찍다 (vyfotit fotku).","r":["sa-寫","jin-眞"]},{"id":"ko-k3-0112","w":"다시","cs":"znovu, opět","en":"again","p":"o","o":"k","ex":"언제 다시 전화할까요?","exc":"Kdy mám zavolat znovu? (-ㄹ까요 → otázka na názor)","m":"다시 = znovu, ještě jednou, od začátku (다시 말해 주세요 = řekněte to prosím znovu). 또 = zase, opět (또 왔어요? = Zase jsi přišel?)."},{"id":"ko-k3-0113","w":"차","cs":"čaj","en":"tea","p":"n","o":"s","ex":"커피 마실까요? 차 마실까요?","exc":"Dáme si kávu, nebo čaj? (-ㄹ까요 → návrh)","m":"茶 čaj = čaj (stejný kořen je ve slově 녹차 = zelený čaj). Pozor na záměnu se stejným slovem 차 (車 = auto), význam vždy napoví sloveso (마시다 = pít vs. 타다 = jet).","r":["cha-茶"]},{"id":"ko-k3-0114","w":"냉동고","cs":"mrazák, mraznička","en":"freezer","p":"n","o":"s","ex":"냉동고 청소할까요?","exc":"Uklidíme mrazák? (-ㄹ까요 → návrh)","m":"冷 studený + 凍 zmrznout + 庫 sklad = mrazicí sklad, tedy mrazák. Srovnej se slovem 냉장고 (lednička), kde je místo 凍 (zmrznout) kořen 藏 (ukládat).","r":["naeng-冷","dong-凍","go-庫"]},{"id":"ko-k3-0115","w":"아이스크림","cs":"zmrzlina","en":"ice cream","p":"n","o":"e","ex":"아이스크림 냉장고에 넣을까요?","exc":"Mám dát tu zmrzlinu do ledničky? (에 → kam; -을까요 → otázka na názor)","m":"Výpůjčka z anglického ‚ice cream‘. V korejštině se zmrzlina ‚jí‘ slovesem 먹다 (아이스크림을 먹다)."}],"gram":{"id":"ko-k3-g04","w":"-(으)ㄹ까요?","en":"Shall we…?, I wonder…","cs":"máme…?, mám…?; copak asi…? (návrh nebo domněnka)","vy":"Koncovka -ㄹ까요? (po samohlásce nebo ㄹ) a -을까요? (po souhlásce) se připojuje ke kmeni slovesa či přídavného jména. S podmětem ‚já‘ nebo ‚my‘ slouží ke zdvořilému návrhu či nabídce (‚Máme…? / Mám…?‘). U třetí osoby nebo dějů mimo naši kontrolu vyjadřuje zvědavou domněnku (‚Copak asi…? / Myslíš, že…?‘).","m":"Jeden tvar, dvě nálady: když mluvíš o nás (‚Půjdeme na film?‘), je to přátelský návrh; když o počasí či jiných lidech (‚Bude zítra pršet?‘), je to přemýšlivé ‚copak asi…‘.","s":[["내일 비가 올까요?","Myslíš, že bude zítra pršet? / Copak asi bude zítra pršet?"],["내일 우리 영화 볼까요?","Půjdeme se zítra podívat na film?"],["이 사람은 누구일까요?","Kdo asi je tenhle člověk?"],["우유 마실까요? 주스 마실까요?","Dáme si mléko, nebo džus?"],["저 가방 안에 뭐가 있을까요?","Copak asi je v tamté tašce?"],["어제 했을까요?","Myslíš, že to včera udělala?"],["누가 전화했을까요?","Kdo asi volal?"],["어제 탈리아나가 한국에 왔을까요?","Myslíš, že Taliana přijela včera do Koreje?"],["지금 바빠요? 이따가 올까요?","Máš teď napilno? Mám přijít později?"],["아니요. 지금 시간 있어요. 여기 앉으세요.","Ne, teď mám čas. Posaďte se prosím tady."],["책을 어디에 놓을까요?","Kam mám položit tu knihu?"],["언제 다시 전화할까요?","Kdy mám zavolat znovu?"],["여기에서 사진 찍을까요?","Vyfotíme se tady?"],["커피 마실까요? 차 마실까요?","Dáme si kávu? Nebo si dáme čaj?"],["제가 도와줄까요?","Mám vám pomoct?"],["떡 같이 먹을까요?","Dáme si spolu rýžové koláčky?"]]}};
Object.assign(MM.mnRoots, {"si-始":["시","始","začátek, začít"],"jak-作":["작","作","dělat, tvořit"],"jeon-電":["전","電","elektřina"],"hwa-話":["화","話","řeč, hovor"],"san-山":["산","山","hora"],"sa-寫":["사","寫","opsat, zobrazit"],"jin-眞":["진","眞","pravý, skutečný"],"cha-茶":["차","茶","čaj"],"naeng-冷":["냉","冷","studený, chladný"],"dong-凍":["동","凍","zmrznout, ledový"],"go-庫":["고","庫","sklad, zásobárna"]});

